local addonName, addon = ...

addon.Capture = addon.Capture or {}
local Capture = addon.Capture

-- Captured guides keyed by full Guidelime name (e.g. "TUGs The Ultimate (Leveling) Guides 30-31 Duskwood")
Capture.guides = {}
-- Ordered list of captured guide names
Capture.guideOrder = {}
-- Reverse index: questId -> { { name = guideName, title = title, minLevel = n, maxLevel = n }, ... }
Capture.questSources = {}
Capture.questSourcesBuilt = false

-- Marker embedded in details of catch-up guides generated by this addon
addon.CATCHUP_MARKER = "GuidelimeCatchUpAutoGenerated"

local function isGeneratedGuideText(text)
	if type(text) ~= "string" then return false end
	return text:find(addon.CATCHUP_MARKER, 1, true) ~= nil
		or text:find("CatchUpGuidelimeAutoGenerated", 1, true) ~= nil
end

local function storeGuide(guideObj, rawText, group)
	if type(guideObj) ~= "table" or not guideObj.name then return end

	local text = rawText
	if type(text) ~= "string" then
		text = guideObj.text
	end
	if type(text) ~= "string" or text == "" then return end

	local isCatchUp = isGeneratedGuideText(text)

	local entry = {
		name = guideObj.name,
		title = guideObj.title or guideObj.name,
		group = guideObj.group or group or "",
		minLevel = guideObj.minLevel,
		maxLevel = guideObj.maxLevel,
		next = guideObj.next,
		faction = guideObj.faction,
		races = guideObj.races,
		excludedRaces = guideObj.excludedRaces,
		classes = guideObj.classes,
		excludedClasses = guideObj.excludedClasses,
		flavors = guideObj.flavors,
		excludedFlavors = guideObj.excludedFlavors,
		hardcore = guideObj.hardcore,
		text = text,
		isCatchUp = isCatchUp,
	}

	if not Capture.guides[entry.name] then
		table.insert(Capture.guideOrder, entry.name)
	end
	Capture.guides[entry.name] = entry
	Capture.questSourcesBuilt = false
end

-- Hook Guidelime.registerGuide IMMEDIATELY at file load time.
-- Because Guidelime_CatchUp depends on Guidelime and sorts before TUGs/Sage/MarkyMark/Shiku/etc.,
-- we intercept guide packs cleanly without modifying any Guidelime files.
if Guidelime and type(Guidelime.registerGuide) == "function" and not Capture._hooked then
	Capture._hooked = true
	local origRegisterGuide = Guidelime.registerGuide
	Guidelime.registerGuide = function(guide, group)
		local rawText = type(guide) == "string" and guide or (type(guide) == "table" and guide.text or nil)
		local result = origRegisterGuide(guide, group)
		if result then
			storeGuide(result, rawText, group)
		end
		return result
	end
end

-- Re-register persisted catch-up/merged guides and import custom/debug guides
function Capture.ImportLateGuides()
	if GuidelimeCatchUpCharDB and Guidelime and Guidelime.registerGuide then
		if type(GuidelimeCatchUpCharDB.savedCatchUpGuides) == "table" then
			for _, saved in pairs(GuidelimeCatchUpCharDB.savedCatchUpGuides) do
				if type(saved) == "table" and type(saved.text) == "string" and saved.text ~= "" then
					if not Capture.guides[saved.name] then
						pcall(Guidelime.registerGuide, saved.text, saved.group)
					end
				end
			end
		end
		if GuidelimeCatchUpCharDB.savedCatchUpGuide then
			local saved = GuidelimeCatchUpCharDB.savedCatchUpGuide
			if type(saved.text) == "string" and saved.text ~= "" then
				if not Capture.guides[saved.name] then
					pcall(Guidelime.registerGuide, saved.text, saved.group)
				end
			end
		end
	end

	-- Ingest GuidelimeData.customGuides
	if GuidelimeData and type(GuidelimeData.customGuides) == "table" then
		for _, rawText in pairs(GuidelimeData.customGuides) do
			if type(rawText) == "string" and rawText ~= "" then
				if addon.Parser and addon.Parser.ParseHeader then
					local meta = addon.Parser.ParseHeader(rawText, "Custom guides")
					if meta and meta.name and not Capture.guides[meta.name] then
						storeGuide(meta, rawText, meta.group)
					end
				end
			end
		end
	end

	-- If Guidelime debug mode exposed Guidelime.addon.guides, import any guides registered earlier
	if Guidelime and Guidelime.addon and type(Guidelime.addon.guides) == "table" then
		for name, g in pairs(Guidelime.addon.guides) do
			if not Capture.guides[name] and type(g) == "table" and type(g.text) == "string" then
				storeGuide(g, g.text, g.group)
			end
		end
	end
end

function Capture.GetGuide(name)
	if not name then return nil end
	local g = Capture.guides[name]
	if g then return g end
	Capture.ImportLateGuides()
	return Capture.guides[name]
end

-- Build a reverse index of which non-catch-up guides accept each questId
function Capture.EnsureQuestSourceIndex()
	if Capture.questSourcesBuilt then return end
	Capture.questSources = {}
	for _, name in ipairs(Capture.guideOrder) do
		local g = Capture.guides[name]
		if g and not g.isCatchUp and addon.Parser and addon.Parser.GuideApplies(g) then
			for tagType, idStr in g.text:gmatch("%[([Qq][AaPpCcTt])%s*(%d+)") do
				local qid = tonumber(idStr)
				if qid then
					local upper = tagType:upper()
					if upper == "QA" or upper == "QP" then
						local list = Capture.questSources[qid]
						if not list then
							list = {}
							Capture.questSources[qid] = list
						end
						local already = false
						for _, existing in ipairs(list) do
							if existing.name == g.name then
								already = true
								break
							end
						end
						if not already then
							table.insert(list, {
								name = g.name,
								title = g.title or g.name,
								group = g.group,
								minLevel = g.minLevel or 0,
								maxLevel = g.maxLevel or 0,
							})
						end
					end
				end
			end
		end
	end
	Capture.questSourcesBuilt = true
end

-- Find the best earlier guide name (preferring same group & lower level than targetGuide) that accepts questId
function Capture.FindSourceGuide(questId, targetGuide)
	Capture.EnsureQuestSourceIndex()
	local sources = Capture.questSources[questId]
	if not sources or #sources == 0 then return nil end

	local targetGroup = targetGuide and targetGuide.group
	local targetMin = targetGuide and (targetGuide.minLevel or 999) or 999
	local targetName = targetGuide and targetGuide.name

	local best, bestScore
	for _, src in ipairs(sources) do
		if src.name ~= targetName then
			local score = 0
			if targetGroup and src.group == targetGroup then score = score + 100 end
			if src.minLevel <= targetMin then score = score + 50 end
			score = score - math.abs((targetMin < 999 and targetMin or 60) - src.minLevel) * 0.1
			if not best or score > bestScore then
				best = src
				bestScore = score
			end
		end
	end
	if not best then return nil end
	if best.minLevel > 0 and best.maxLevel > 0 then
		return string.format("%d-%d %s", best.minLevel, best.maxLevel, best.title)
	elseif best.minLevel > 0 then
		return string.format("%d %s", best.minLevel, best.title)
	end
	return best.title
end

-- Return sorted list of applicable non-catch-up guides for the dropdown
function Capture.GetApplicableGuides()
	Capture.ImportLateGuides()
	local list = {}
	for _, name in ipairs(Capture.guideOrder) do
		local g = Capture.guides[name]
		if g and not g.isCatchUp and addon.Parser and addon.Parser.GuideApplies(g) then
			table.insert(list, g)
		end
	end
	table.sort(list, function(a, b)
		if (a.group or "") ~= (b.group or "") then
			return (a.group or "") < (b.group or "")
		end
		if (a.minLevel or 0) ~= (b.minLevel or 0) then
			return (a.minLevel or 0) < (b.minLevel or 0)
		end
		if (a.maxLevel or 0) ~= (b.maxLevel or 0) then
			return (a.maxLevel or 0) < (b.maxLevel or 0)
		end
		return (a.name or "") < (b.name or "")
	end)
	return list
end
